CREATE TABLE tickets (id INTEGER PRIMARY KEY, title TEXT NOT NULL, assignee TEXT);
INSERT INTO tickets (title, assignee) VALUES
  ('Fix login', 'Ada'),
  ('Write docs', NULL),
