SELECT COUNT(*) AS all_rows,
       COUNT(assignee) AS assigned,
       COUNT(DISTINCT assignee) AS people
FROM tickets;

SELECT ROUND(SUM(p.price * o.quantity), 2) AS revenue
FROM orders o
JOIN products p ON p.id = o.product_id;
